// Writes src/lib/wobnimoBundle.generated.ts from the wobnimo npm package (MIT, https://github.com/Pouryaak/wobnimo).
// The phone draws mascots in a WebView that cannot reach the network, so the engine is inlined as a string.
// Usage: node scripts/sync-wobnimo-bundle.mjs [path/to/wobnimo/dist/wobnimo.js]   (--check compares, writes nothing)
import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const args = process.argv.slice(2);
const check = args.includes('--check');
const source = args.find((a) => !a.startsWith('--')) ?? join(here, '..', 'node_modules', 'wobnimo', 'dist', 'wobnimo.js');
const target = join(here, '..', 'src', 'lib', 'wobnimoBundle.generated.ts');

const code = readFileSync(source, 'utf8').trim();
const tail = code.match(/export\s*\{([^}]*)\}\s*;?$/);
if (!tail) throw new Error('wobnimo.js no longer ends with an export list; update this script.');
const members = tail[1].split(',').map((part) => {
    const [local, exported = local] = part.trim().split(/\s+as\s+/);
    return `${exported}:${local}`;
});
const script = `${code.slice(0, tail.index)}window.__wobnimo={${members.join(',')}};`;
if (script.includes('</script')) throw new Error('bundle contains a closing script tag');

const out = `// Generated by scripts/sync-wobnimo-bundle.mjs from wobnimo (MIT). Do not edit.\n`
    + `export const WOBNIMO_SCRIPT = ${JSON.stringify(script)};\n`;
if (check) {
    const current = readFileSync(target, 'utf8');
    if (current !== out) { console.error('wobnimoBundle.generated.ts is out of date; run the script.'); process.exit(1); }
} else {
    writeFileSync(target, out);
    console.log(`wrote ${target} (${(out.length / 1024).toFixed(0)} KB)`);
}
